            if (spec.infinite === false) {
                targetSlide = ReactDOM.findDOMNode(spec.trackRef).children[
                    spec.slideIndex
                ];
            } else {
                targetSlide = ReactDOM.findDOMNode(spec.trackRef).children[
                    spec.slideIndex + spec.slidesToShow + 1
                ];
            }

            if (targetSlide) {
                targetLeft =
                    targetSlide.offsetLeft * -1 +
                    (spec.listWidth - targetSlide.offsetWidth) / 2;
            }
        }
    }

    return targetLeft;
};

