            style,
            className,
            children,
        } = this.props;

        const sliderProps = obj.pickOthers(
            ['className', 'style', 'slideDirection'],
            this.props
        );
        const slideCount = React.Children.count(children);

        if (slideCount === 0) {
            // 没有 item 时不显示 slider
            return null;
        } else if (slideCount === 1) {
            // 单个 item 时不显示箭头和控制器
